(()=>{'use strict';
const R=window.HandbookReview,base='https://github.com/'+R.repo,main=document.querySelector('#main');
const labels={de:{comment:'Hinweis geben',reviews:'Experten-Review · v1.1',title:'Fachlichen Hinweis eingeben',placeholder:'Was fehlt, ist unklar oder sollte geändert werden? Stichpunkte reichen.',send:'Auf GitHub speichern →',close:'Schließen',hint:'GitHub öffnet einen vorausgefüllten Vorgang. Erst mit „Submit new issue“ wird dein Hinweis zentral gespeichert. Ein GitHub-Konto ist erforderlich; Kommentare sind öffentlich.',overview:'Review-Übersicht',all:'Alle Reviews auf GitHub ↗',loading:'Reviews werden geladen …',empty:'Noch keine Review-Vorgänge vorhanden.',error:'Die Übersicht konnte nicht geladen werden. Öffne die Reviews direkt auf GitHub.',open:'Offen',closed:'Geschlossen',process:'Hinweis → fachliche Entscheidung → Copilot-Entwurf → menschliche Prüfung → Veröffentlichung. Geschlossen bedeutet nicht automatisch umgesetzt; die begründete Entscheidung steht im Vorgang.',copy:'Redaktionsauftrag kopieren',copied:'Auftrag kopiert.',ai:'Copilot wird vom Verantwortlichen auf GitHub beauftragt. Diese Seite führt selbst keine KI-Bearbeitung aus.',quote:'Markierte Passage',version:'Version',limit:'Die neuesten 100 Vorgänge wurden geprüft. Ältere Reviews findest du über den GitHub-Link.',pending:'Versionsdaten werden geladen. Bitte erneut versuchen.',unavailable:'Die genaue Version konnte nicht geladen werden. Bitte lade die Seite erneut.'},en:{comment:'Leave feedback',reviews:'Expert review · v1.1',title:'Enter technical feedback',placeholder:'What is missing, unclear or needs changing? Bullet points are enough.',send:'Save on GitHub →',close:'Close',hint:'GitHub opens a prefilled issue. Your feedback is saved centrally only after “Submit new issue”. A GitHub account is required; comments are public.',overview:'Review overview',all:'All reviews on GitHub ↗',loading:'Loading reviews …',empty:'No review issues yet.',error:'Could not load reviews. Open them directly on GitHub.',open:'Open',closed:'Closed',process:'Feedback → technical decision → Copilot draft → human review → publication. Closed does not necessarily mean implemented; read the recorded decision.',copy:'Copy editorial task',copied:'Task copied.',ai:'A maintainer assigns the issue to Copilot on GitHub. This page does not run AI editing.',quote:'Selected passage',version:'Version',limit:'The latest 100 issues were checked. See older reviews on GitHub.',pending:'Loading version metadata. Please try again.',unavailable:'Exact version metadata could not be loaded. Please reload.'},zh:{comment:'提供反馈',reviews:'专家评审 · v1.1',title:'输入专业意见',placeholder:'缺少什么？哪里不清楚？需要修改什么？简短要点即可。',send:'在 GitHub 上保存 →',close:'关闭',hint:'GitHub 将打开预填的问题。点击“Submit new issue”后才会集中保存。需要 GitHub 账号；评论公开可见。',overview:'评审概览',all:'查看 GitHub 上的全部评审 ↗',loading:'正在加载评审…',empty:'暂无评审。',error:'无法加载评审，请直接打开 GitHub。',open:'待处理',closed:'已关闭',process:'意见 → 专业决定 → Copilot 草稿 → 人工审核 → 发布。已关闭不一定代表已落实，请查看决定说明。',copy:'复制编辑任务',copied:'任务已复制。',ai:'负责人在 GitHub 上将任务交给 Copilot。本页面不会自动执行 AI 编辑。',quote:'选中文本',version:'版本',limit:'已检查最新的100个问题。更早的评审请在 GitHub 上查看。',pending:'正在加载版本信息，请稍后重试。',unavailable:'无法加载准确版本，请刷新页面。'}};
const lang=()=>window.L?.lang||'de',t=k=>labels[lang()][k];
let version=null,versionError=false;
fetch('version.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error();return r.json();}).then(v=>{if(!/^[a-f0-9]{40}$/.test(v.sourceCommit))throw Error();version=v;}).catch(()=>{versionError=true;});
const dialog=document.createElement('dialog');dialog.className='review-dialog';dialog.setAttribute('aria-label','Expert review');document.body.append(dialog);
function node(tag,text,cls){const el=document.createElement(tag);if(text!==undefined)el.textContent=text;if(cls)el.className=cls;return el;}
function button(text,fn){const el=node('button',text,'btn');el.type='button';el.addEventListener('click',fn);return el;}
function link(text,url){const a=node('a',text,'btn');a.href=url;a.target='_blank';a.rel='noopener noreferrer';return a;}
function frame(title){dialog.replaceChildren();dialog.append(button(t('close'),()=>dialog.close()),node('h2',title));if(!dialog.open)dialog.showModal();}
function promptFor(r){return ['Prepare an editorial pull request for Reliability Handbook.', 'Original reviewer comment: '+r.comment,'Anchor: '+r.anchor,'Version: '+r.sourceCommit,'Language: '+r.language,'Quote: '+r.quote,'Read .github/copilot-instructions.md. Preserve original feedback; clarify ambiguity rather than inventing facts. Explain the proposed changes and link the review issue. Human approval is required before publishing.'].join('\n');}
function openFeedback(c,index){
 if(!version){frame(t('title'));dialog.append(node('p',t(versionError?'unavailable':'pending')));return;}
 const selection=window.getSelection();let quote='';if(selection?.anchorNode&&main.contains(selection.anchorNode)&&selection.focusNode&&main.contains(selection.focusNode))quote=selection.toString().slice(0,1200);
 const anchor=window.REVIEW_ANCHORS[c.id];const section=index===null?null:anchor?.sections[index];if(!anchor||(index!==null&&!section))return;
 const current=window.BOOKS[lang()].chapters.find(x=>x.id===c.id);
 const record={...version,language:lang(),anchor:section?.id||c.id,chapter:current.title,section:index===null?'':current.sections[index].title,url:location.origin+location.pathname+'#'+c.id+(index===null?'':'/section-'+index),quote,comment:''};
 frame(t('title'));dialog.append(node('p',record.chapter+(record.section?' / '+record.section:''),'review-context'),node('p',t('version')+': '+record.version+' · '+record.contentVersion+' · '+record.sourceCommit,'review-context'));
 if(quote)dialog.append(node('h3',t('quote')),node('blockquote',quote));
 const input=node('textarea');input.maxLength=2500;input.required=true;input.placeholder=t('placeholder');input.setAttribute('aria-label',t('title'));dialog.append(input);
 const actions=node('div',undefined,'review-actions'),send=link(t('send'),'#');send.setAttribute('aria-disabled','true');
 input.addEventListener('input',()=>{record.comment=input.value.trim();send.href=record.comment?R.issueUrl(record):'#';send.setAttribute('aria-disabled',String(!record.comment));});
 send.addEventListener('click',e=>{if(!record.comment){e.preventDefault();input.reportValidity();}});
 const copy=button(t('copy'),async()=>{record.comment=input.value.trim();if(!record.comment){input.reportValidity();return;}try{await navigator.clipboard.writeText(promptFor(record));copy.textContent=t('copied');}catch{const out=node('textarea',promptFor(record));out.readOnly=true;dialog.append(out);out.select();}});
 actions.append(send,copy);dialog.append(actions,node('p',t('hint'),'review-help'),node('p',t('ai'),'review-help'));input.focus();
}
async function overview(){frame(t('overview'));dialog.append(node('p',t('process'),'review-help'),link(t('all'),base+'/issues?q='+encodeURIComponent('is:issue "[Handbook review]" in:title')));const status=node('p',t('loading'));dialog.append(status);try{const response=await fetch('https://api.github.com/repos/'+R.repo+'/issues?state=all&per_page=100&sort=created&direction=desc',{headers:{Accept:'application/vnd.github+json'}});if(!response.ok)throw Error();const all=await response.json();const issues=all.filter(x=>!x.pull_request&&x.title.startsWith('[Handbook review]'));status.textContent=issues.length?'':t('empty');if(all.length===100)dialog.append(node('p',t('limit'),'review-help'));for(const issue of issues){if(!issue.html_url.startsWith(base+'/issues/'))continue;const row=node('article',undefined,'review-item');row.append(link(issue.title,issue.html_url),node('small',(issue.state==='open'?t('open'):t('closed'))+' · '+issue.user.login+' · '+new Date(issue.created_at).toLocaleDateString()));dialog.append(row);}}catch{status.textContent=t('error');status.className='review-error';}}
function enhance(){
 let nav=document.querySelector('.review-nav');if(!nav){nav=button(t('reviews'),overview);nav.classList.add('review-nav');document.querySelector('.sidebar-footer').prepend(nav);}else if(nav.textContent!==t('reviews'))nav.textContent=t('reviews');
 const id=location.hash.slice(1).split('/')[0],c=window.BOOKS.de.chapters.find(x=>x.id===id);if(!c)return;
 const heading=main.querySelector('.page-title');if(heading&&!heading.querySelector('.review-button')){const b=button(t('comment')+' · '+t('version')+' 1.1',()=>openFeedback(c,null));b.classList.add('review-button');heading.append(b);}
 main.querySelectorAll('.reader-section').forEach((el,i)=>{if(el.querySelector('.review-button'))return;const b=button(t('comment'),()=>openFeedback(c,i));b.classList.add('review-button');el.prepend(b);});
}
new MutationObserver(enhance).observe(document.querySelector('.shell'),{childList:true,subtree:true});enhance();
})();
